import itertools,random

def reachable(p):
    n=len(p)
    # x are 1..n positions, y=p[x-1]
    A=[]
    for k in range(n):
        s=set()
        xk=k+1; yk=p[k]
        for i in range(n):
            xi=i+1; yi=p[i]
            if i==k or (xi-xk)*(yi-yk)<0:
                s.add(i)
        A.append(s)
    start=frozenset(range(n))
    q=[start]; vis={start}
    while q:
        S=q.pop()
        for k in list(S):
            T=frozenset(S & A[k])
            if T not in vis:
                vis.add(T); q.append(T)
    return vis

def comp(a,b,p):
    xa,ya=a+1,p[a]; xb,yb=b+1,p[b]
    return (xa-xb)*(ya-yb)>0

for n in range(1,8):
    vals=[]
    for p in itertools.permutations(range(1,n+1)):
        vis=reachable(p)
        vals.append(len(vis))
    print(n, min(vals),max(vals),sorted(set(vals))[:10], 'countdistinct',len(set(vals)))

import itertools

def sets_from_chains(p):
    n=len(p)
    # all decreasing chains by x increasing y decreasing
    chains=[[]]
    for mask in range(1<<n):
        idx=[i for i in range(n) if mask>>i&1]
        ok=True
        for a,b in zip(idx,idx[1:]):
            if p[a]<=p[b]: ok=False;break
        if ok: chains.append(idx)
    seen={}
    for T in chains:
        S=[]
        for i in range(n):
            survive=True
            for k in T:
                if i==k: continue
                if (i-k)*(p[i]-p[k])>0: survive=False; break
            if survive:S.append(i)
        seen.setdefault(tuple(S),[]).append(tuple(T))
    col=[v for v in seen.values() if len(v)>1]
    return seen,col

