def collisions(p):
    n=len(p)
    seen={}
    for mask in range(1<<n):
        T=[i for i in range(n) if mask>>i&1]
        ok=all(p[T[j]]>p[T[j+1]] for j in range(len(T)-1))
        if not ok: continue
        S=[]
        for i in range(n):
            survive=True
            for k in T:
                if i==k: continue
                if (i-k)*(p[i]-p[k])>0: survive=False; break
            if survive:S.append(i)
        seen.setdefault(tuple(S),[]).append(tuple(T))
    return [v for v in seen.values() if len(v)>1]

