import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    # maxLExact[x][r] = max L among constraints with (X=x, R=r)
    maxLExact = [[0]*(N+1) for _ in range(N+1)]

    for _ in range(M):
        L, R, X = map(int, input().split())
        if L > maxLExact[X][R]:
            maxLExact[X][R] = L

    # A[x][r] = max L among constraints with (X=x, R<=r)
    A = [[0]*(N+1) for _ in range(N+1)]
    for x in range(1, N+1):
        cur = 0
        rowE = maxLExact[x]
        rowA = A[x]
        for r in range(1, N+1):
            v = rowE[r]
            if v > cur:
                cur = v
            rowA[r] = cur

    # combinations C[n][k], n<=N
    fact = [1]*(N+1)
    for i in range(1, N+1):
        fact[i] = fact[i-1]*i % MOD
    invfact = [1]*(N+1)
    invfact[N] = pow(fact[N], MOD-2, MOD)
    for i in range(N, 0, -1):
        invfact[i-1] = invfact[i]*i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

    # dp[l][r]: number for interval [l, r]
    dp = [[0]*(N+2) for _ in range(N+2)]
    for i in range(1, N+2):
        dp[i][i-1] = 1  # empty interval

    for length in range(1, N+1):
        n1 = length - 1
        for l in range(1, N-length+2):
            r = l + length - 1
            total = 0
            for k in range(l, r+1):
                # invalid if there exists constraint with X=k, R<=r, L>=l
                if A[k][r] >= l:
                    continue
                total += comb(n1, k-l) * dp[l][k-1] % MOD * dp[k+1][r]
            dp[l][r] = total % MOD

    print(dp[1][N])

if __name__ == '__main__':
    main()

