import sys
sys.setrecursionlimit(1000000)

MOD = 998244353


def main() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    A = [int(next(it)) - 1 for _ in range(N)]

    # Reverse graph of original functional graph
    rev = [[] for _ in range(N)]
    for i, to in enumerate(A):
        rev[to].append(i)

    # Kosaraju (iterative) to get SCCs
    vis = [0] * N
    order = []
    for s in range(N):
        if vis[s]:
            continue
        stack = [(s, 0)]
        while stack:
            v, st = stack.pop()
            if st == 0:
                if vis[v]:
                    continue
                vis[v] = 1
                stack.append((v, 1))
                to = A[v]
                if not vis[to]:
                    stack.append((to, 0))
            else:
                order.append(v)

    comp = [-1] * N
    cid = 0
    for s in reversed(order):
        if comp[s] != -1:
            continue
        comp[s] = cid
        stack = [s]
        while stack:
            v = stack.pop()
            for u in rev[v]:
                if comp[u] == -1:
                    comp[u] = cid
                    stack.append(u)
        cid += 1

    C = cid

    # Condensation graph: each component has outdegree <= 1
    parent = [-1] * C
    for i in range(N):
        u = comp[i]
        v = comp[A[i]]
        if u != v:
            parent[u] = v

    children = [[] for _ in range(C)]
    roots = []
    for u in range(C):
        p = parent[u]
        if p == -1:
            roots.append(u)
        else:
            children[p].append(u)

    # Returns g_u[t] = number of assignments in subtree of u with value(u) <= t
    # (i.e. prefix sums of exact-value counts f_u)
    def dfs(u: int):
        acc = None  # temporary f_u[t]

        for ch in children[u]:
            gch = dfs(ch)
            if acc is None:
                # multiply by 1 for first child
                acc = gch[:]
            else:
                for t in range(1, M + 1):
                    acc[t] = (acc[t] * gch[t]) % MOD

        if acc is None:
            # Leaf: f_u[t] = 1, so g_u[t] = t
            g = [0] * (M + 1)
            for t in range(1, M + 1):
                g[t] = t
            return g

        # Prefix sum: g_u[t] = sum_{s=1..t} f_u[s]
        run = 0
        for t in range(1, M + 1):
            run += acc[t]
            if run >= MOD:
                run -= MOD
            acc[t] = run
        acc[0] = 0
        return acc

    ans = 1
    for r in roots:
        gr = dfs(r)
        ans = (ans * gr[M]) % MOD

    print(ans)


if __name__ == "__main__":
    main()

