    facs = []
    primes_set = set()
    for x in A:
        d = {}
        v = x
        while v > 1:
            p = spf[v]
            e = 0
            while v % p == 0:
                v //= p
                e += 1
            d[p] = e
            primes_set.add(p)
        facs.append(d)

    ans = 1

    # Independent contribution per prime
    for p in primes_set:
        c = [facs[i].get(p, 0) for i in range(N - 1)]
        M = sum(c)  # maximum possible exponent when min exponent is fixed at 0
        if M == 0:
            continue

        # p^v for v=0..M
        powp = [1] * (M + 1)
        for v in range(1, M + 1):
            powp[v] = (powp[v - 1] * p) % MOD

        # dp0[v]: total weight for current position exponent=v, zero not visited yet
        # dp1[v]: total weight for current position exponent=v, zero visited
        dp0 = [0] * (M + 1)
        dp1 = [0] * (M + 1)

        # Initial x1 can be any 0..M; weight includes p^{x1}
        dp1[0] = 1
        for v in range(1, M + 1):
            dp0[v] = powp[v]

        for d in c:
            ndp0 = [0] * (M + 1)
            ndp1 = [0] * (M + 1)

            if d == 0:
                # only stay at same exponent
                for v in range(M + 1):
                    w = powp[v]
                    a0 = dp0[v]
                    if a0:
                        ndp0[v] = (ndp0[v] + a0 * w) % MOD
                    a1 = dp1[v]
                    if a1:
                        ndp1[v] = (ndp1[v] + a1 * w) % MOD
            else:
                for v in range(M + 1):
                    a0 = dp0[v]
                    a1 = dp1[v]
                    if not a0 and not a1:
                        continue

                    u = v - d
