import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    A = data[1:1+n]

    vmax = 100000

    # Euler's totient for all 1..vmax
    phi = list(range(vmax + 1))
    for i in range(2, vmax + 1):
        if phi[i] == i:
            for j in range(i, vmax + 1, i):
                phi[j] -= phi[j] // i

    # Divisors for all values up to vmax
    divs = [[] for _ in range(vmax + 1)]
    for d in range(1, vmax + 1):
        for m in range(d, vmax + 1, d):
            divs[m].append(d)

    T = [0] * (vmax + 1)  # T[d] = sum of weights of previous elements divisible by d

    ans = 0
    w = 1  # 2^(i-1)
    out = []

    for x in A:
        s = 0
        dx = divs[x]
        for d in dx:
            s += phi[d] * T[d]
        s %= MOD

        ans = (ans * 2 + s) % MOD
        out.append(str(ans))

        for d in dx:
            v = T[d] + w
            if v >= MOD:
                v -= MOD
            T[d] = v

        w <<= 1
        if w >= MOD:
            w -= MOD

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

