import sys

def main() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    A = data[1:1 + n]

    m = max(A)

    # Smallest prime factor sieve
    spf = list(range(m + 1))
    if m >= 1:
        spf[1] = 1
    p = 2
    while p * p <= m:
        if spf[p] == p:  # p is prime
            for x in range(p * p, m + 1, p):
                if spf[x] == x:
                    spf[x] = p
        p += 1

    # omega[x] = number of prime factors of x with multiplicity
    omega = [0] * (m + 1)
    for x in range(2, m + 1):
        omega[x] = omega[x // spf[x]] + 1

    xor_sum = 0
    for v in A:
        xor_sum ^= omega[v]

    print("Anna" if xor_sum != 0 else "Bruno")

if __name__ == "__main__":
    main()

