from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)

        # Group pairs by their larger endpoint y (with x < y).
        by_right = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        # cnt[x] = how many active pairs currently have left endpoint x.
        cnt = [0] * (n + 1)
        # single_idx[x] = pair index if cnt[x] == 1, else -1.
        single_idx = [-1] * (n + 1)

        top1 = 0  # largest active x
        top2 = 0  # second largest active x

        base = 0
        gain = [0] * m  # extra valid subarrays gained by removing this exact pair

        for r in range(1, n + 1):
            # Activate pairs with y == r.
            for x, idx in by_right[r]:
                c = cnt[x]
                cnt[x] = c + 1
                if c == 0:
                    single_idx[x] = idx
                elif c == 1:
                    single_idx[x] = -1

                # Maintain top two distinct active x values.
                if x > top1:
                    top2 = top1
                    top1 = x
                elif top1 > x > top2:
                    top2 = x

            # With all pairs present, valid starts for subarrays ending at r are (top1+1..r).
            base += r - top1

            # If the current max constraint top1 comes from exactly one pair,
            # removing that pair would relax boundary from top1 to top2 at this r.
            if top1 > 0 and cnt[top1] == 1:
                gain[single_idx[top1]] += top1 - top2

        return base + max(gain)

