import sys


def main() -> None:
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    # L[i] = number of distinct values in A[1..i] (1-indexed)
    L = [0] * (N + 1)
    seen = [0] * (N + 1)
    cnt = 0
    for i, x in enumerate(A, 1):
        if not seen[x]:
            seen[x] = 1
            cnt += 1
        L[i] = cnt

    # R[i] = number of distinct values in A[i..N] (1-indexed)
    R = [0] * (N + 2)
    seen = [0] * (N + 1)
    cnt = 0
    for i in range(N, 0, -1):
        x = A[i - 1]
        if not seen[x]:
            seen[x] = 1
            cnt += 1
        R[i] = cnt

    # Segment tree (lazy): range add / range max
    arr = [L[i] for i in range(1, N + 1)]  # index i -> position i-1

    size = 1
    while size < N:
        size <<= 1
    NEG_INF = -10 ** 18

    d = [NEG_INF] * (2 * size)
    lz = [0] * size

    for i, v in enumerate(arr):
        d[size + i] = v
    for i in range(size - 1, 0, -1):
        d[i] = d[2 * i] if d[2 * i] > d[2 * i + 1] else d[2 * i + 1]

    log = size.bit_length() - 1

    def all_apply(k: int, f: int) -> None:
        d[k] += f
        if k < size:
            lz[k] += f

    def push(k: int) -> None:
        z = lz[k]
        if z:
            all_apply(2 * k, z)
            all_apply(2 * k + 1, z)
            lz[k] = 0

    def range_add(l: int, r: int, f: int) -> None:
        # add f to [l, r)
        if l >= r:
            return
        l += size
        r += size
        l0, r0 = l, r

        for i in range(log, 0, -1):
            if ((l0 >> i) << i) != l0:
                push(l0 >> i)
            if ((r0 >> i) << i) != r0:
                push((r0 - 1) >> i)

        while l < r:
            if l & 1:
                all_apply(l, f)
                l += 1
            if r & 1:
                r -= 1
                all_apply(r, f)
            l >>= 1
            r >>= 1

        l, r = l0, r0
        for i in range(1, log + 1):
            if ((l >> i) << i) != l:
                k = l >> i
                d[k] = d[2 * k] if d[2 * k] > d[2 * k + 1] else d[2 * k + 1]
                d[k] += lz[k]
            if ((r >> i) << i) != r:
                k = (r - 1) >> i
                d[k] = d[2 * k] if d[2 * k] > d[2 * k + 1] else d[2 * k + 1]
                d[k] += lz[k]

    def range_max(l: int, r: int) -> int:
        # max on [l, r)
        if l >= r:
            return NEG_INF
        l += size
        r += size

        for i in range(log, 0, -1):
            if ((l >> i) << i) != l:
                push(l >> i)
            if ((r >> i) << i) != r:
                push((r - 1) >> i)

        sml = NEG_INF
        smr = NEG_INF
        while l < r:
            if l & 1:
                if d[l] > sml:
                    sml = d[l]
                l += 1
            if r & 1:
                r -= 1
                if d[r] > smr:
                    smr = d[r]
            l >>= 1
            r >>= 1

        return sml if sml > smr else smr

    # Sweep j as the right end of the middle segment.
    # Maintained value for each i:
    # V_i = distinct(A[1..i]) + distinct(A[i+1..j])
    last = [0] * (N + 1)
    ans = 0

    for j in range(1, N + 1):
        x = A[j - 1]
        l = max(1, last[x])
        r = j - 1
        if l <= r:
            # i in [l, r] gain +1 for distinct(A[i+1..j])
            # mapped to positions [l-1, j-1)
            range_add(l - 1, j - 1, 1)
        last[x] = j

        if 2 <= j <= N - 1:
            best_left_mid = range_max(0, j - 1)  # i in [1, j-1]
            cand = best_left_mid + R[j + 1]
            if cand > ans:
                ans = cand

    print(ans)


