import sys

def ceil_div(a, b):
    return (a + b - 1) // b

def min_cost_for_w(w, A, P, B, Q):
    INF = 10**30
    best = INF

    # Transformation preserving capacity:
    # (x, y) -> (x-B, y+A) changes cost by -B*P + A*Q.
    # If B*P >= A*Q, reducing x is never worse, so an optimum exists with x < B.
    # Otherwise, reducing y is never worse, so an optimum exists with y < A.
    if B * P >= A * Q:
        lim = min(B - 1, ceil_div(w, A))
        for x in range(lim + 1):
            rem = w - A * x
            y = 0 if rem <= 0 else ceil_div(rem, B)
            c = x * P + y * Q
            if c < best:
                best = c
    else:
        lim = min(A - 1, ceil_div(w, B))
        for y in range(lim + 1):
            rem = w - B * y
            x = 0 if rem <= 0 else ceil_div(rem, A)
            c = x * P + y * Q
            if c < best:
                best = c

    return best

def feasible(target, processes, X):
    total = 0
    for A, P, B, Q in processes:
        total += min_cost_for_w(target, A, P, B, Q)
        if total > X:
            return False
    return total <= X

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    X = int(next(it))
    processes = []
    for _ in range(N):
        A = int(next(it))
        P = int(next(it))
        B = int(next(it))
        Q = int(next(it))
        processes.append((A, P, B, Q))

    lo, hi = 0, 1_000_000_001  # lo feasible, hi infeasible
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid, processes, X):
            lo = mid
        else:
            hi = mid

    print(lo)

if __name__ == "__main__":
    main()

