class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # Precompute binomial coefficients C[n][r] for 0 <= n,r <= L
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for n in range(L + 1):
            C[n][0] = 1
            C[n][n] = 1
            for r in range(1, n):
                C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD

        # g[t] = number of popcount-operations needed to reduce t to 1
        # for 1 <= t <= L
        INF = 10**9
        g = [INF] * (L + 1)
        g[1] = 0
        for t in range(2, L + 1):
            g[t] = 1 + g[t.bit_count()]

        # For x > 1: steps(x) = 1 + g[popcount(x)].
        # So popcount t is valid iff g[t] <= k-1.
        valid = [False] * (L + 1)
        for t in range(1, L + 1):
            if g[t] <= k - 1:
                valid[t] = True

        # Count numbers y with 0 <= y < n (n given by s), represented in L bits,
        # that have exactly t set bits.
        def count_less_with_ones(t: int) -> int:
            ans = 0
            ones_used = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    # Put 0 at this bit (making number smaller), then choose remaining bits freely
                    rem = L - i - 1
                    need = t - ones_used
                    if 0 <= need <= rem:
                        ans = (ans + C[rem][need]) % MOD

                    # Continue tight path by putting 1
                    ones_used += 1
                    if ones_used > t:
                        break
            return ans

        res = 0
        for t in range(1, L + 1):
            if valid[t]:
                res = (res + count_less_with_ones(t)) % MOD

        return res

