from typing import *
MOD=10**9+7
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        L=len(s)
        # Binomial coefficients
        C=[[0]*(L+1) for _ in range(L+1)]
        for n in range(L+1):
            C[n][0]=C[n][n]=1
            for r in range(1,n):
                C[n][r]=(C[n-1][r-1]+C[n-1][r])%MOD

        # steps for t to reduce to 1 via repeated popcount
        g=[10**9]*(L+1)
        g[1]=0
        for i in range(2,L+1):
            g[i]=1+g[i.bit_count()]

        valid=[False]*(L+1)
        for t in range(1,L+1):
            if g[t] <= k-1:
                valid[t]=True

        def count_less_with_ones(t:int)->int:
            if t<0 or t>L:
                return 0
            ans=0
            ones=0
            for i,ch in enumerate(s):
                if ch=='1':
                    rem=L-i-1
                    need=t-ones
                    if 0<=need<=rem:
                        ans=(ans+C[rem][need])%MOD
                    ones+=1
                    if ones>t:
                        break
            return ans

        ans=0
        for t in range(1,L+1):
            if valid[t]:
                ans=(ans+count_less_with_ones(t))%MOD
        return ans

