import sys
sys.setrecursionlimit(1 << 25)

def solve():
    input = sys.stdin.readline
    N, M, Q = map(int, input().split())
    ST = [tuple(map(int, input().split())) for _ in range(M)]
    LR = [tuple(map(int, input().split())) for _ in range(Q)]

    # This is a conservative checker for each query (not optimized for worst-case).
    # It builds equality classes among towns by endpoint equalities,
    # then creates strict inequality edges and checks DAG feasibility.
    # (May be too slow on maximum constraints.)
    from collections import deque

    out = []

    for L, R in LR:
        persons = ST[L-1:R]

        parent = list(range(N + 1))
        size = [1] * (N + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        # Equalities: A[S] == A[T]
        for s, t in persons:
            union(s, t)

        # Compress classes
        roots = {}
        idx = 0
        for v in range(1, N + 1):
            r = find(v)
            if r not in roots:
                roots[r] = idx
                idx += 1
        K = idx

        g = [set() for _ in range(K)]
        bad = False

        def cid(x):
            return roots[find(x)]

        for s, t in persons:
            cs = cid(s)
            if s < t:
                # interior must be greater than base
                for x in range(s + 1, t):
                    cx = cid(x)
                    if cx == cs:
                        bad = True
                        break
                    g[cs].add(cx)   # base < interior
                if bad:
                    break
            else:
                # interior must be smaller than base
                for x in range(t + 1, s):
                    cx = cid(x)
                    if cx == cs:
                        bad = True
                        break
                    g[cx].add(cs)   # interior < base
                if bad:
                    break

        if bad:
            out.append("No")
            continue

        indeg = [0] * K
        for u in range(K):
            for v in g[u]:
                indeg[v] += 1

        dq = deque([i for i in range(K) if indeg[i] == 0])
        cnt = 0
        while dq:
            u = dq.popleft()
            cnt += 1
            for v in g[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    dq.append(v)

        out.append("Yes" if cnt == K else "No")

    print("\n".join(out))

if __name__ == "__main__":
    solve()

