import sys
MOD=998244353

def main():
    N,M,K=map(int,sys.stdin.readline().split())
    X=list(map(int,sys.stdin.readline().split()))

    # Approximate model via arch-factorization style counting.
    m=K-1

    C=[[0]*(m+1) for _ in range(m+1)]
    for n in range(m+1):
        C[n][0]=C[n][n]=1
        for r in range(1,n):
            C[n][r]=(C[n-1][r-1]+C[n-1][r])%MOD

    def surj(n,colors):
        res=0
        for j in range(colors+1):
            term=C[colors][j]*pow(colors-j,n,MOD)
            if j&1:
                res=(res-term)%MOD
            else:
                res=(res+term)%MOD
        return res

    arch=[0]*(N+1)
    tail=[0]*(N+1)
    for t in range(N+1):
        if t>=1:
            arch[t]=surj(t-1,m)
        tail[t]=surj(t,m)

    dp=[0]*(N+1)
    dp[0]=1
    for _ in range(M-1):
        ndp=[0]*(N+1)
        for s in range(N+1):
            if dp[s]==0:
                continue
            base=dp[s]
            for t in range(1,N-s+1):
                v=arch[t]
                if v:
                    ndp[s+t]=(ndp[s+t]+base*v)%MOD
        dp=ndp

    ans=0
    for used in range(N+1):
        if dp[used]==0:
            continue
        ans=(ans+dp[used]*tail[N-used])%MOD

    print(ans%MOD)

