from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        INF = 10**18  # safely above k (k <= 1e15)

        # Only up to max(odd_count, even_count) factorials are needed (<= 50)
        max_cnt = (n + 1) // 2
        fact = [1] * (max_cnt + 1)
        for i in range(1, max_cnt + 1):
            v = fact[i - 1] * i
            fact[i] = v if v < INF else INF

        def mul_cap(a: int, b: int) -> int:
            v = a * b
            return v if v < INF else INF

        # Number of completions when remaining counts are (ro, re)
        # and the next chosen number must be odd iff next_odd=True.
        def count_completions(ro: int, re: int, next_odd: bool) -> int:
            m = ro + re
            if m == 0:
                return 1

            first_parity_need = (m + 1) // 2
            second_parity_need = m // 2

            if next_odd:
                if ro != first_parity_need or re != second_parity_need:
                    return 0
            else:
                if re != first_parity_need or ro != second_parity_need:
                    return 0

            return mul_cap(fact[ro], fact[re])

        unused = list(range(1, n + 1))  # kept sorted
        rem_odd = (n + 1) // 2
        rem_even = n // 2

        ans = []
        prev = None

        for _ in range(n):
            chosen = None

            for x in unused:
                # Must alternate parity with previous element.
                if prev is not None and ((x & 1) == (prev & 1)):
                    continue

                ro2, re2 = rem_odd, rem_even
                if x & 1:
                    ro2 -= 1
                else:
                    re2 -= 1

                # After choosing x, next must have opposite parity.
                cnt = count_completions(ro2, re2, next_odd=((x & 1) == 0))

                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    ans.append(x)
                    rem_odd, rem_even = ro2, re2
                    prev = x
                    unused.remove(x)
                    break

            if chosen is None:
                return []

        return ans

