class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w))
            g[v].append((u, w))

        parent = [-1] * n
        order = []
        stack = [0]
        parent[0] = -2

        while stack:
            u = stack.pop()
            order.append(u)
            for v, w in g[u]:
                if parent[v] == -1:
                    parent[v] = u
                    stack.append(v)

        dp0 = [0] * n  # parent edge not selected
        dp1 = [0] * n  # parent edge selected

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in g[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gain = w + dp1[v] - dp0[v]
                    if gain > 0:
                        gains.append(gain)

            if gains:
                gains.sort(reverse=True)

                take0 = min(k, len(gains))
                dp0[u] = base + sum(gains[:take0])

                take1 = min(max(k - 1, 0), len(gains))
                dp1[u] = base + sum(gains[:take1])
            else:
                dp0[u] = base
                dp1[u] = base

        return dp0[0]

