class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')  # exactly two '*'
        la, lb, lc = len(a), len(b), len(c)

        def kmp_occ(text: str, pat: str) -> List[int]:
            if pat == "":
                return list(range(len(text) + 1))

            m = len(pat)
            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                    lps[i] = j

            res = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pat[j]:
                    j = lps[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        res.append(i - m + 1)
                        j = lps[j - 1]
            return res

        occA = kmp_occ(s, a)
        occB = kmp_occ(s, b)
        occC = kmp_occ(s, c)

        ans = float('inf')

        pa = 0
        best_i = None
        pc = 0

        # For each occurrence of middle part b at jpos,
        # choose latest valid start of a and earliest valid start of c.
        for jpos in occB:
            lim_i = jpos - la  # need i + la <= jpos
            while pa < len(occA) and occA[pa] <= lim_i:
                best_i = occA[pa]  # latest valid i so far
                pa += 1
            if best_i is None:
                continue

            need_k = jpos + lb  # need jpos + lb <= k
            while pc < len(occC) and occC[pc] < need_k:
                pc += 1
            if pc == len(occC):
                break

            cur_len = occC[pc] + lc - best_i
            if cur_len < ans:
                ans = cur_len

        return -1 if ans == float('inf') else ans

