def step(state,i,N):
    # state tuple counts len N
    c=list(state)
    n=[0]*N
    for j,v in enumerate(c,1):
        if v==0: continue
        if i<j: nj=j-1
        elif i>j: nj=j+1
        else: nj=j
        n[nj-1]+=v
    return tuple(n)

