from typing import List
from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)

        def factor_score(remove_idx: int) -> int:
            g = 0
            l = 1
            has_element = False

            for i, x in enumerate(nums):
                if i == remove_idx:
                    continue
                if not has_element:
                    g = x
                    l = x
                    has_element = True
                else:
                    g = gcd(g, x)
                    l = l * x // gcd(l, x)

            return 0 if not has_element else g * l

        best = factor_score(-1)  # remove nothing
        for i in range(n):
            best = max(best, factor_score(i))

        return best

