    for ch in s:
        o = ord(ch)
        if 65 <= o <= 90:
            toggled.append(chr(o + 32))
        else:
            toggled.append(chr(o - 32))

    ans = []
    for k in ks:
        p = k - 1
        idx = p % n
        block = p // n
        if block.bit_count() & 1:
            ans.append(toggled[idx])
        else:
            ans.append(s[idx])

    sys.stdout.write(' '.join(ans))

