class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = Counter(nums)

        for x in sorted(freq.keys(), reverse=True):
            if (total - x) % 2 != 0:
                continue
            s = (total - x) // 2
            if freq.get(s, 0) - (1 if s == x else 0) > 0:
                return x

