from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        # Already a zero array without processing any query.
        if all(x == 0 for x in nums):
            return 0

        # For each index i, we only care about reachable sums up to nums[i].
        masks = [(1 << (x + 1)) - 1 for x in nums]

        # dp[i]: bitset of reachable decrements for index i.
        # bit s = 1 means sum s can be formed from processed queries covering i.
        dp = [1] * n  # only sum 0 reachable initially

        def all_reachable() -> bool:
            for i, target in enumerate(nums):
                if ((dp[i] >> target) & 1) == 0:
                    return False
            return True

        # Process queries in order; first prefix making every index reachable is answer.
        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                dp[i] |= (dp[i] << val) & masks[i]

            if all_reachable():
                return k

        return -1

