import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        d = len(str(n))
        lower = 0 if d == 1 else 10 ** (d - 1)
        upper = 10 ** d

        # Sieve of Eratosthenes up to the largest state value.
        is_prime = [True] * upper
        if upper > 0:
            is_prime[0] = False
        if upper > 1:
            is_prime[1] = False
        p = 2
        while p * p < upper:
            if is_prime[p]:
                start = p * p
                is_prime[start:upper:p] = [False] * (((upper - 1 - start) // p) + 1)
            p += 1

        # n and m themselves must be non-prime.
        if is_prime[n] or is_prime[m]:
            return -1

        INF = 10**30
        dist = [INF] * upper
        dist[n] = n  # cost includes the initial value n
        pq = [(n, n)]  # (cost, value)

        powers = [10 ** i for i in range(d)]

        while pq:
            cost, u = heapq.heappop(pq)
            if cost != dist[u]:
                continue
            if u == m:
                return cost

            for p10 in powers:
                digit = (u // p10) % 10

                # Increase this digit by 1
                if digit < 9:
                    v = u + p10
                    if v < upper and not is_prime[v]:
                        nc = cost + v
                        if nc < dist[v]:
                            dist[v] = nc
                            heapq.heappush(pq, (nc, v))

                # Decrease this digit by 1
                if digit > 0:
                    v = u - p10
                    if v >= lower and not is_prime[v]:
                        nc = cost + v
                        if nc < dist[v]:
                            dist[v] = nc
                            heapq.heappush(pq, (nc, v))

        return -1

