class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        def z_full(arr):
            m = len(arr)
            z = [0] * m
            l = r = 0
            for i in range(1, m):
                if i < r:
                    v = z[i - l]
                    rr = r - i
                    z[i] = v if v < rr else rr
                while i + z[i] < m and arr[z[i]] == arr[i + z[i]]:
                    z[i] += 1
                if i + z[i] > r:
                    l = i
                    r = i + z[i]
            return z

        z0 = z_full(nums)

        def z_suffix(start):
            m = n - start
            z = [0] * m
            l = r = 0
            for i in range(1, m):
                if i < r:
                    v = z[i - l]
                    rr = r - i
                    z[i] = v if v < rr else rr
                while i + z[i] < m and nums[start + z[i]] == nums[start + i + z[i]]:
                    z[i] += 1
                if i + z[i] > r:
                    l = i
                    r = i + z[i]
            return z

        ans = 0
        for i in range(1, n - 1):
            m = n - i
            z = z_suffix(i)
            prefix_ok = z0[i] >= i
            for t in range(1, m):
                if (prefix_ok and t >= i) or (t + t <= m and z[t] >= t):
                    ans += 1

