def can_within_one(s: str, t: str) -> bool:
    n, m = len(s), len(t)
    if abs(n - m) > 1:
        return False

    if n == m:
        mism = 0
        for a, b in zip(s, t):
            if a != b:
                mism += 1
                if mism > 1:
                    return False
        return True

    # Ensure s is the shorter string (length differs by exactly 1 here).
    if n > m:
        s, t = t, s
        n, m = m, n

    i = j = 0
    skipped = False
    while i < n and j < m:
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            if skipped:
                return False
            skipped = True
            j += 1  # Skip one char in longer string.

    return True


