from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)

        removable = [False] * n
        for idx in targetIndices:
            removable[idx] = True

        INF = 10**9
        # dp[j] = minimum number of target indices that must be kept
        # to match pattern[:j] as a subsequence of processed source prefix
        dp = [INF] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            keep_cost = 1 if removable[i] else 0
            # Reverse order to avoid reusing source[i] more than once
            for j in range(m, 0, -1):
                if ch == pattern[j - 1]:
                    cand = dp[j - 1] + keep_cost
                    if cand < dp[j]:
                        dp[j] = cand

        min_kept_targets = dp[m]
        return len(targetIndices) - min_kept_targets

