from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # threshold >= 1 (per constraints), so if reachability is possible,
        # we can always keep at most one outgoing edge per node.
        # Thus we only need the minimum max weight X such that using edges with w <= X,
        # every node can reach node 0.

        # Reverse edges: original a->b becomes b->a.
        # Then "every node reaches 0" in original == "0 reaches every node" in reversed.
        rev_edges = [(b, a, w) for a, b, w in edges]

        def can(mx: int) -> bool:
            g = [[] for _ in range(n)]
            for u, v, w in rev_edges:
                if w <= mx:
                    g[u].append(v)

            seen = [False] * n
            seen[0] = True
            q = deque([0])
            reached = 1

            while q:
                u = q.popleft()
                for v in g[u]:
                    if not seen[v]:
                        seen[v] = True
                        reached += 1
                        q.append(v)

            return reached == n

        weights = sorted({w for _, _, w in edges})
        if not can(weights[-1]):
            return -1

        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if can(weights[mid]):
                hi = mid
            else:
                lo = mid + 1

        return weights[lo]

