class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Pair houses from both ends:
        # pair k -> (k, n-1-k), for k in [0, n/2 - 1].
        # Let left color = a, right color = b.
        # Constraints become:
        # 1) a != b (equidistant houses differ)
        # 2) a differs from previous pair's left color (adjacent on left side)
        # 3) b differs from previous pair's right color (adjacent on right side)
        m = n // 2
        INF = 10**30

        # dp[a][b] = min cost up to current pair with colors (a,b)
        # for current pair, only valid when a != b.
        dp = [[INF] * 3 for _ in range(3)]

        # Initialize for pair 0
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        # Process remaining pairs
        for k in range(1, m):
            ndp = [[INF] * 3 for _ in range(3)]
            for a in range(3):
                for b in range(3):
                    if a == b:
                        continue

                    add = cost[k][a] + cost[n - 1 - k][b]
                    best_prev = INF

                    for pa in range(3):
                        if pa == a:
                            continue
                        for pb in range(3):
                            if pb == b:
                                continue
                            if dp[pa][pb] < best_prev:
                                best_prev = dp[pa][pb]

                    ndp[a][b] = best_prev + add

            dp = ndp

        ans = INF
        for a in range(3):
            for b in range(3):
                if a != b and dp[a][b] < ans:
                    ans = dp[a][b]

        return ans

