            y, _ = col[r - 1]
            if y > del_time[r]:
                del_time[r] = y

    INF = 10**30
    disappear = [INF] * (N + 1)
    for i in range(1, N + 1):
        r = rank[i]
        if r <= m:
            disappear[i] = del_time[r]

    Q = int(next(it))
    out = []
    for _ in range(Q):
        T = int(next(it)); A = int(next(it))
        out.append('Yes' if disappear[A] > T else 'No')

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

