class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]  # unmatched indices for each letter
        score = 0

        for i, ch in enumerate(s):
            c = ord(ch) - 97
            m = 25 - c  # mirror letter index

            if stacks[m]:
                j = stacks[m].pop()  # closest unmatched mirror index
                score += i - j
            else:
                stacks[c].append(i)

        return score

