class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}

        def at_most(K: int) -> int:
            if K < 0:
                return 0

            last = {v: -1 for v in vowels}
            left = 0
            consonants = 0
            total = 0

            for right, ch in enumerate(word):
                if ch in vowels:
                    last[ch] = right
                else:
                    consonants += 1

                while consonants > K:
                    if word[left] not in vowels:
                        consonants -= 1
                    left += 1

                min_last_vowel = min(last.values())
                if min_last_vowel >= left:
                    total += (min_last_vowel - left + 1)

            return total

        return at_most(k) - at_most(k - 1)

