def brute(word,k):
    v=set('aeiou')
    n=len(word)
    c=0
    for i in range(n):
        for j in range(i,n):
            s=word[i:j+1]
            if all(ch in s for ch in 'aeiou') and sum(ch not in v for ch in s)==k:
                c+=1
    return c

